using api::v2::Types::Create_t = struct Create_t



     : public Entity_t<jsoncons::json> {






   Create_t(const jsoncons::json& _data,
            const uint64_t        id)
       : Entity_t(_data,
                  id) {
   }  




   explicit Create_t(const jsoncons::json& _data)
       : Entity_t(_data,
                  std::nullopt) {
   }  



   ~Create_t() override = default;  

 }

